cd examples/delivery-plans/top-down-delivery-planning
python3 - <<'PY'
import re, sys, glob, pathlib
try:
    import yaml
except ImportError:
    print("PyYAML not available; doing structural check only"); yaml=None
bad=[]
files=sorted(glob.glob("**/*.md", recursive=True))
fm_files=[f for f in files if pathlib.Path(f).name!="README.md"]
for f in fm_files:
    txt=pathlib.Path(f).read_text()
    m=re.match(r'^---\n(.*?)\n---\n', txt, re.S)
    if not m:
        bad.append((f,"no front-matter")); continue
    if yaml:
        try:
            d=yaml.safe_load(m.group(1))
            if 'layer' not in d: bad.append((f,"missing layer"))
        except Exception as e:
            bad.append((f,f"YAML error: {e}"))
print(f"checked {len(fm_files)} front-matter files")
if bad:
    for f,e in bad: print(" FAIL",f,e)
    sys.exit(1)
print("all front-matter parses as valid YAML with a 'layer' key")
PY
